import json
import os
from typing import Any, Dict, Optional, Tuple

import boto3
from botocore.exceptions import BotoCoreError, ClientError


class BedrockModelResolver:
    def __init__(self, region_name: Optional[str] = None):
        self.region_name = (
            region_name
            or os.getenv("AWS_REGION")
            or os.getenv("AWS_DEFAULT_REGION")
            or "us-east-1"
        )
        self.bedrock = boto3.client("bedrock", region_name=self.region_name)
        self.bedrock_runtime = boto3.client("bedrock-runtime", region_name=self.region_name)

    def resolve_inference_resource(
        self,
        preferred_model_id: Optional[str] = None,
        provider: Optional[str] = None,
        require_on_demand: bool = False,
    ) -> Tuple[str, Dict[str, Any]]:
        paginator = self.bedrock.get_paginator("list_foundation_models")
        summaries = []
        for page in paginator.paginate():
            summaries.extend(page.get("modelSummaries", []))

        if not summaries:
            raise RuntimeError("No Bedrock foundation models were returned by list_foundation_models.")

        candidates = []
        for summary in summaries:
            model_id = summary.get("modelId", "")
            provider_name = summary.get("providerName", "")
            inference_types = summary.get("inferenceTypesSupported", []) or []

            if preferred_model_id and model_id != preferred_model_id:
                continue
            if provider and provider_name.lower() != provider.lower():
                continue
            if require_on_demand and "ON_DEMAND" not in inference_types:
                continue

            candidates.append(summary)

        if preferred_model_id and not candidates:
            raise ValueError(f"Requested Bedrock model_id not found or not eligible: {preferred_model_id}")

        if not candidates:
            preferred_fallbacks = [
                "anthropic.claude-3-haiku-20240307-v1:0",
                "amazon.titan-text-express-v1",
                "meta.llama3-8b-instruct-v1:0",
                "mistral.mistral-7b-instruct-v0:2",
            ]
            indexed = {m.get("modelId"): m for m in summaries}
            for fallback in preferred_fallbacks:
                if fallback in indexed:
                    candidates = [indexed[fallback]]
                    break

        if not candidates:
            candidates = summaries

        def sort_key(item: Dict[str, Any]) -> Tuple[int, int, str]:
            inference_types = item.get("inferenceTypesSupported", []) or []
            model_id = item.get("modelId", "")
            provider_name = item.get("providerName", "")
            supports_on_demand = 0 if "ON_DEMAND" in inference_types else 1
            provider_rank = 0 if provider_name.lower() == "anthropic" else 1
            return (supports_on_demand, provider_rank, model_id)

        selected = sorted(candidates, key=sort_key)[0]
        return selected["modelId"], selected

    def invoke(
        self,
        prompt: str,
        preferred_model_id: Optional[str] = None,
        provider: Optional[str] = None,
        max_tokens: int = 256,
        temperature: float = 0.7,
    ) -> Dict[str, Any]:
        model_id, metadata = self.resolve_inference_resource(
            preferred_model_id=preferred_model_id,
            provider=provider,
            require_on_demand=False,
        )

        try:
            response = self.bedrock_runtime.converse(
                modelId=model_id,
                messages=[
                    {
                        "role": "user",
                        "content": [{"text": prompt}],
                    }
                ],
                inferenceConfig={
                    "maxTokens": max_tokens,
                    "temperature": temperature,
                },
            )
        except (ClientError, BotoCoreError) as e:
            raise RuntimeError(f"Bedrock invoke failed for model {model_id}: {e}") from e

        output = response.get("output", {})
        message = output.get("message", {})
        content = message.get("content", []) or []

        text_parts = []
        for part in content:
            if "text" in part:
                text_parts.append(part["text"])

        return {
            "provider": "Amazon Bedrock",
            "region": self.region_name,
            "resolved_model_id": model_id,
            "model_metadata": metadata,
            "text": "\n".join(text_parts).strip(),
            "raw_response": response,
        }


def run_workflow(
    prompt: str,
    preferred_model_id: Optional[str] = None,
    provider: Optional[str] = None,
    region_name: Optional[str] = None,
) -> Dict[str, Any]:
    resolver = BedrockModelResolver(region_name=region_name)
    return resolver.invoke(
        prompt=prompt,
        preferred_model_id=preferred_model_id,
        provider=provider,
    )
